/**
 * The storybook map of Disney California Adventure, drawn over real geography
 * from OpenStreetMap (src/art/dcaGeo.ts, generated by scripts/build-dca-map.mjs)
 * in the same style as the Disneyland map: storybook paper, soft land colors
 * and little original details. Nothing is traced from any official map art.
 *
 * Hard rules: no characters, logos, castles or three-circle shapes, no film
 * props, and no names drawn on the map itself (labels and medallions are
 * added on top by ParkMap).
 *
 * Map data © OpenStreetMap contributors (ODbL).
 */
import { DCA_GEO_CANVAS, DCA_GEO_FEATURES, DCA_GEO_LANDS, DCA_GEO_LAYERS } from './dcaGeo';
import { bird, carrousel, cloud, M, type ParkLand, sparkle, spinner } from './parkMap';
import type { Shape } from './shapes';

type Hex = `#${string}`;
type Pt = { x: number; y: number };

export const DCA_CANVAS = DCA_GEO_CANVAS;
const W = DCA_CANVAS.width;
const H = DCA_CANVAS.height;

const LAND_TINT: Record<string, Hex> = {
  'dca-buena-vista-street': '#F3DCC6',
  'dca-hollywood-land': '#EEDDEA',
  'dca-avengers-campus': '#DDE2EC',
  'dca-cars-land': '#F1D2B6',
  'dca-san-fransokyo-square': '#F1DADF',
  'dca-pixar-pier': '#DCE6F6',
  'dca-paradise-gardens-park': '#D8EAD0',
  'dca-grizzly-peak': '#D0E2C0',
};

const BUILDING: Record<string, Hex> = {
  'dca-buena-vista-street': '#E6BCA9',
  'dca-hollywood-land': '#DDB0C9',
  'dca-avengers-campus': '#B9C3D6',
  'dca-cars-land': '#D9A07A',
  'dca-san-fransokyo-square': '#DDB0B8',
  'dca-pixar-pier': '#B8CCEA',
  'dca-paradise-gardens-park': '#C8DDB0',
  'dca-grizzly-peak': '#C9A983',
  other: '#D9CDB9',
};

const ROCK: Record<string, Hex> = {
  'dca-cars-land': '#C9774E',
  'dca-grizzly-peak': '#B98A66',
  other: '#B9A58A',
};

const L = DCA_GEO_LAYERS;
const f = DCA_GEO_FEATURES;

/** A big wheel seen from the front, standing on its spot. */
function bigWheel(c: Pt, r: number): Shape[] {
  return [
    { kind: 'circle', cx: c.x, cy: c.y - r, r, fill: 'none', stroke: M.gold, strokeWidth: 1.4 },
    ...[0, 30, 60, 90, 120, 150].map((a): Shape => {
      const rad = (a * Math.PI) / 180;
      return { kind: 'line', x1: c.x - Math.cos(rad) * r, y1: c.y - r - Math.sin(rad) * r, x2: c.x + Math.cos(rad) * r, y2: c.y - r + Math.sin(rad) * r, stroke: M.gold, strokeWidth: 0.6 };
    }),
    ...[0, 60, 120, 180, 240, 300].map((a, i): Shape => {
      const rad = (a * Math.PI) / 180;
      return { kind: 'circle', cx: +(c.x + Math.cos(rad) * r).toFixed(1), cy: +(c.y - r + Math.sin(rad) * r).toFixed(1), r: 1.8, fill: [M.red, M.blue, M.gold][i % 3] };
    }),
    { kind: 'polygon', points: `${c.x},${c.y - r} ${c.x - r * 0.45},${c.y} ${c.x + r * 0.45},${c.y}`, fill: 'none', stroke: M.gold, strokeWidth: 1 },
  ];
}

/** A rocky peak seen from above. */
function peakCap(c: Pt, r: number): Shape {
  const pts: string[] = [];
  for (let i = 0; i < 12; i++) {
    const rr = i % 2 ? r * 0.55 : r;
    const a = (i / 12) * Math.PI * 2;
    pts.push(`${(c.x + rr * Math.cos(a)).toFixed(1)},${(c.y + rr * Math.sin(a)).toFixed(1)}`);
  }
  return { kind: 'polygon', points: pts.join(' '), fill: '#9A6E50', stroke: '#7A5238', strokeWidth: 0.6 };
}

/** Painted sparkles that twinkle (corners only). */
export const DCA_TWINKLES: Pt[] = [
  { x: W - 40, y: 60 },
  { x: 50, y: 60 },
  { x: W - 60, y: H - 140 },
];

export const dcaMap: Shape[] = [
  { kind: 'rect', x: 0, y: 0, w: W, h: H, fill: M.paper },
  { kind: 'path', d: L.ground, fill: M.ground },
  ...Object.entries(DCA_GEO_LANDS).map(([id, land]): Shape => ({ kind: 'path', d: land.outline, fill: LAND_TINT[id] ?? M.ground })),
  { kind: 'path', d: L.greens, fill: M.green },
  { kind: 'path', d: L.forest, fill: M.forest },
  { kind: 'path', d: L.trees, fill: M.tree },
  { kind: 'path', d: L.water, fill: M.water, stroke: M.waterEdge, strokeWidth: 0.8 },
  { kind: 'path', d: L.streams, fill: 'none', stroke: M.water, strokeWidth: 3 },
  ...Object.values(DCA_GEO_LANDS).map((land): Shape => ({
    kind: 'path', d: land.outline, fill: 'none', stroke: M.edge, strokeWidth: 1.2, dash: '4 4', opacity: 0.8,
  })),
  { kind: 'path', d: L.walkAreas, fill: M.walk },
  { kind: 'path', d: L.mainPaths, fill: 'none', stroke: M.walkEdge, strokeWidth: 8 },
  { kind: 'path', d: L.paths, fill: 'none', stroke: M.walkEdge, strokeWidth: 5 },
  { kind: 'path', d: L.mainPaths, fill: 'none', stroke: M.walk, strokeWidth: 6.4 },
  { kind: 'path', d: L.paths, fill: 'none', stroke: M.walk, strokeWidth: 3.4 },
  { kind: 'path', d: L.steps, fill: 'none', stroke: M.walkEdge, strokeWidth: 3.4, dash: '1 1.5' },
  ...Object.entries(L.rock).map(([land, d]): Shape => ({ kind: 'path', d, fill: ROCK[land] ?? ROCK.other, stroke: '#8E6A52', strokeWidth: 0.5 })),
  ...Object.entries(L.buildings).map(([land, d]): Shape => ({ kind: 'path', d, fill: BUILDING[land] ?? BUILDING.other, stroke: '#8E7A6A', strokeWidth: 0.6 })),
  { kind: 'path', d: L.roofs, fill: '#EFE5CF', stroke: M.edge, strokeWidth: 0.6, dash: '2 1.5' },
  { kind: 'path', d: L.coaster, fill: 'none', stroke: M.red, strokeWidth: 2 },
  { kind: 'path', d: L.monorail, fill: 'none', stroke: '#9AA4B8', strokeWidth: 2.6 },
  peakCap(f.peak, 12),
  ...carrousel(f.carousel, 7),
  ...spinner(f.swings),
  ...spinner(f.zephyr),
  ...bigWheel(f.wheel, 14),
  cloud(W - 200, 26, 64),
  cloud(40, H - 90, 50),
  bird(W - 140, 100),
  bird(W - 126, 92),
  ...DCA_TWINKLES.map((p) => sparkle(p.x, p.y, 5)),
  // Title cartouche (bottom left) and compass rose (bottom right).
  { kind: 'path', d: `M30 ${H - 70} Q30 ${H - 86} 46 ${H - 86} L206 ${H - 86} Q222 ${H - 86} 222 ${H - 70} L222 ${H - 40} Q222 ${H - 24} 206 ${H - 24} L46 ${H - 24} Q30 ${H - 24} 30 ${H - 40} Z`, fill: M.white, stroke: M.edge, strokeWidth: 2 },
  { kind: 'circle', cx: W - 50, cy: H - 60, r: 20, fill: M.white, stroke: M.edge, strokeWidth: 1.5 },
  { kind: 'polygon', points: `${W - 50},${H - 84} ${W - 45},${H - 60} ${W - 50},${H - 36} ${W - 55},${H - 60}`, fill: M.ink, opacity: 0.85 },
  { kind: 'polygon', points: `${W - 50},${H - 84} ${W - 45},${H - 60} ${W - 55},${H - 60}`, fill: M.red },
];

/** Where each land's medallion sits on the whole-park map (tuned so they don't overlap). */
const LABEL_AT: Record<string, Pt> = {
  'dca-buena-vista-street': { x: 470, y: 95 },
  'dca-hollywood-land': { x: 690, y: 150 },
  'dca-avengers-campus': { x: 660, y: 300 },
  'dca-grizzly-peak': { x: 330, y: 220 },
  'dca-paradise-gardens-park': { x: 130, y: 340 },
  'dca-san-fransokyo-square': { x: 430, y: 400 },
  'dca-pixar-pier': { x: 285, y: 505 },
  'dca-cars-land': { x: 530, y: 560 },
};

export const DCA_LANDS: ParkLand[] = Object.entries(DCA_GEO_LANDS).map(([id, land]) => ({
  id,
  label: LABEL_AT[id] ?? land.label,
  view: land.view,
  lanes: land.lanes,
}));

export const dcaMapLabels = [
  { text: 'The Golden State Atlas', x: 126, y: H - 55, size: 11, style: 'title' },
  { text: 'N', x: W - 50, y: H - 96, size: 10, style: 'plain' },
] as const;
